CREATE TABLE prepaid_renewal_create_recovery_jobs (period_id TEXT PRIMARY KEY NOT NULL REFERENCES prepaid_periods(period_id), contract_id TEXT NOT NULL REFERENCES prepaid_contracts(contract_id), ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal BETWEEN 1 AND 9007199254740991), api_origin TEXT NOT NULL CHECK(api_origin IN ('https://checkout.postfinance.ch','https://app-wallee.com')), space_id INTEGER NOT NULL CHECK(typeof(space_id)='integer' AND space_id>0), environment TEXT NOT NULL CHECK(environment IN ('TEST','PRODUCTION')), create_scope_hash TEXT NOT NULL CHECK(length(create_scope_hash)=64 AND create_scope_hash NOT GLOB '*[^0-9a-f]*'), request_fingerprint TEXT NOT NULL CHECK(length(request_fingerprint)=43 AND request_fingerprint NOT GLOB '*[^A-Za-z0-9_-]*'), original_claim_token TEXT NOT NULL CHECK(length(original_claim_token)=36 AND original_claim_token NOT GLOB '*[^a-f0-9-]*'), state TEXT NOT NULL CHECK(state IN ('queued','processing','completed','failed')), attempts INTEGER NOT NULL CHECK(typeof(attempts)='integer' AND attempts BETWEEN 0 AND 8), lease_token TEXT, lease_until INTEGER NOT NULL CHECK(typeof(lease_until)='integer' AND lease_until>=0), next_attempt_at INTEGER NOT NULL CHECK(typeof(next_attempt_at)='integer' AND next_attempt_at>0), last_attempt_at INTEGER CHECK(last_attempt_at IS NULL OR typeof(last_attempt_at)='integer' AND last_attempt_at>0), last_error_code TEXT CHECK(last_error_code IS NULL OR last_error_code IN ('absent','ambiguous','unstable','unavailable','binding','not-claimed','provider-binding')), created_at INTEGER NOT NULL CHECK(typeof(created_at)='integer' AND created_at>0), updated_at INTEGER NOT NULL CHECK(typeof(updated_at)='integer' AND updated_at>=created_at), CHECK(next_attempt_at>=created_at), CHECK((state='processing' AND length(lease_token)=36 AND lease_token NOT GLOB '*[^a-f0-9-]*' AND lease_until>updated_at AND lease_until<=updated_at+130 AND last_attempt_at IS NOT NULL) OR (state!='processing' AND lease_token IS NULL AND lease_until=0)), CHECK((state IN ('processing','completed','failed') AND attempts>0) OR state='queued'), CHECK(state!='failed' OR attempts=8)) ;
