CREATE TRIGGER prepaid_renewal_create_recovery_admission BEFORE INSERT ON prepaid_renewal_create_recovery_jobs BEGIN SELECT CASE WHEN NEW.created_at>unixepoch() OR NEW.updated_at!=NEW.created_at OR NEW.next_attempt_at!=NEW.created_at OR NEW.state!='queued' OR NEW.attempts!=0 OR NEW.last_attempt_at IS NOT NULL OR NEW.last_error_code IS NOT NULL THEN RAISE(ABORT,'Invalid CREATE recovery admission') WHEN NOT EXISTS(SELECT 1 FROM prepaid_periods p JOIN prepaid_contracts c ON c.contract_id=p.contract_id JOIN prepaid_renewal_requests r ON r.period_id=p.period_id AND r.contract_id=c.contract_id JOIN postfinance_mutations m ON m.scope_hash=r.create_scope_hash JOIN prepaid_purchase_targets t ON t.contract_id=c.contract_id JOIN prepaid_purchase_projections x ON x.contract_id=c.contract_id AND x.intent_id=t.intent_id JOIN purchase_intents i ON i.intent_id=t.intent_id WHERE p.period_id=NEW.period_id AND c.contract_id=NEW.contract_id AND p.ordinal=NEW.ordinal AND p.ordinal>0 AND c.api_origin=NEW.api_origin AND c.space_id=NEW.space_id AND c.environment=NEW.environment AND r.create_scope_hash=NEW.create_scope_hash AND m.fingerprint=NEW.request_fingerprint AND m.claim_token=NEW.original_claim_token AND m.state IN ('claimed','uncertain') AND m.response_json IS NULL AND x.closed_at IS NOT NULL AND i.state='settled' AND i.provider='postfinance' AND i.provider_scope=(c.api_origin||'|'||c.space_id) AND i.environment=c.environment AND i.owner_id=c.owner_id AND i.organization_id IS c.organization_id AND i.workspace_id IS c.workspace_id AND t.owner_id=c.owner_id AND t.organization_id IS c.organization_id AND t.workspace_id IS c.workspace_id AND NOT EXISTS(SELECT 1 FROM prepaid_create_recoveries z WHERE z.period_id=p.period_id)) THEN RAISE(ABORT,'CREATE recovery source is not bound') END ; END ;
