CREATE TRIGGER prepaid_renewal_create_recovery_immutable BEFORE UPDATE ON prepaid_renewal_create_recovery_jobs BEGIN SELECT CASE WHEN NEW.period_id IS NOT OLD.period_id OR NEW.contract_id IS NOT OLD.contract_id OR NEW.ordinal IS NOT OLD.ordinal OR NEW.api_origin IS NOT OLD.api_origin OR NEW.space_id IS NOT OLD.space_id OR NEW.environment IS NOT OLD.environment OR NEW.create_scope_hash IS NOT OLD.create_scope_hash OR NEW.request_fingerprint IS NOT OLD.request_fingerprint OR NEW.original_claim_token IS NOT OLD.original_claim_token OR NEW.created_at IS NOT OLD.created_at OR NEW.updated_at>unixepoch() OR NEW.updated_at<OLD.updated_at OR NEW.attempts<OLD.attempts OR NEW.attempts>OLD.attempts+1 OR COALESCE(NEW.last_attempt_at,0)<COALESCE(OLD.last_attempt_at,0) THEN RAISE(ABORT,'CREATE recovery identity is immutable') WHEN OLD.state IN ('completed','failed') AND (NEW.state IS NOT OLD.state OR NEW.attempts IS NOT OLD.attempts OR NEW.next_attempt_at IS NOT OLD.next_attempt_at OR NEW.last_attempt_at IS NOT OLD.last_attempt_at OR NEW.last_error_code IS NOT OLD.last_error_code OR NEW.updated_at IS NOT OLD.updated_at OR NEW.lease_token IS NOT OLD.lease_token OR NEW.lease_until IS NOT OLD.lease_until) THEN RAISE(ABORT,'CREATE recovery is terminal') WHEN NEW.state='processing' AND (NEW.attempts=OLD.attempts+1 AND NOT(OLD.state='queued' OR OLD.state='processing' AND OLD.lease_until<=unixepoch()) OR NEW.attempts=OLD.attempts AND NOT(OLD.state='processing' AND NEW.lease_token=OLD.lease_token AND OLD.lease_until>unixepoch())) THEN RAISE(ABORT,'CREATE recovery lease is unavailable') WHEN NEW.state IN ('queued','completed','failed') AND NOT(OLD.state='processing' AND NEW.attempts=OLD.attempts AND (OLD.lease_until>unixepoch() OR NEW.state='failed' AND OLD.attempts=8)) THEN RAISE(ABORT,'CREATE recovery lease is lost') END ; END ;
