CREATE TRIGGER prepaid_renewal_create_recovery_completion BEFORE UPDATE OF state ON prepaid_renewal_create_recovery_jobs WHEN NEW.state='completed' AND OLD.state!='completed' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM prepaid_create_recoveries r JOIN prepaid_transactions t ON t.period_id=r.period_id AND t.transaction_id=r.transaction_id JOIN postfinance_mutations m ON m.scope_hash=r.scope_hash JOIN postfinance_observation_jobs o ON o.period_id=r.period_id AND o.transaction_id=r.transaction_id WHERE r.period_id=NEW.period_id AND r.contract_id=NEW.contract_id AND r.scope_hash=NEW.create_scope_hash AND r.request_fingerprint=NEW.request_fingerprint AND r.original_claim_token=NEW.original_claim_token AND t.api_origin=NEW.api_origin AND t.space_id=NEW.space_id AND m.state='completed' AND m.fingerprint=NEW.request_fingerprint AND json_extract(m.response_json,'$.id')=t.transaction_id AND o.api_origin=NEW.api_origin AND o.space_id=NEW.space_id AND o.environment=NEW.environment AND o.provenance='create_recovery') THEN RAISE(ABORT,'CREATE recovery observation is missing') END ; END ;
